def backprop(d,initial,support=H.SUPPORT,extended=False,smoke=False):
    started=time.perf_counter()
    tf,tau=H.C.compress_zoh(d.force_t,d.generalized_input(d.force_t,torch.ones((),dtype=H.DT)))
    bounds=[tuple(v*math.log(10) for v in b) for b in support]
    pairs=H.grid(support) if initial=='native' else [(initial['inertia'],initial['damping'])]
    x0=torch.tensor([[math.log(i),math.log(i/c)] for i,c in pairs],dtype=H.DT)
    for j,b in enumerate(bounds):x0[:,j].clamp_(*b)
    x=x0.clone().requires_grad_(True)
    def fun(xx):
        forced,free=H.C.B.zoh_basis(xx[...,0],xx[...,0]-xx[...,1],tf,tau,float(d.t_obs[0]),d.t_obs)
        off,v0=H.C.B._ls_offset_velocity(forced,free,d.q_obs)
        qh=off[...,None]+v0[...,None]*free+forced
        return ((qh-d.q_obs)**2).mean(-1),qh,off,v0
    opt=torch.optim.Adam([x],lr=.05)
    steps=20 if smoke else 6000 if extended else 3000
    for _ in range(steps):
        opt.zero_grad();v=fun(x)[0];torch.nan_to_num(v,nan=1e6,posinf=1e6).sum().backward()
        x.grad=torch.nan_to_num(x.grad);opt.step()
        with torch.no_grad():
            for j,b in enumerate(bounds):x[:,j].clamp_(*b)
    order=torch.argsort(torch.nan_to_num(fun(x)[0],nan=float('inf'))).tolist()[:8]
    candidates=[]
    for k in order:
        def fg(z):
            zz=torch.tensor(z,dtype=H.DT,requires_grad=True);L=fun(zz)[0];g=torch.autograd.grad(L,zz)[0]
            return float(L.detach()),g.detach().numpy()
        rr=minimize(fg,x[k].detach().numpy(),jac=True,bounds=bounds,method='L-BFGS-B',
                    options={'maxiter':10 if smoke else 2000 if extended else 500,'ftol':1e-12,'gtol':1e-8,'maxls':50})
        candidates.append(rr)
    best=min(candidates,key=lambda r:r.fun if np.isfinite(r.fun) else float('inf'))
    z=torch.tensor(best.x,dtype=H.DT);L,q,off,v0=fun(z)
    pg=np.asarray(best.jac).copy()
    for j,(a,b) in enumerate(bounds):
        if best.x[j]<=a+1e-8 and pg[j]>0 or best.x[j]>=b-1e-8 and pg[j]<0:pg[j]=0
    return dict(inertia=math.exp(best.x[0]),damping=math.exp(best.x[0]-best.x[1]),q_hat=q.detach().tolist(),
                runtime_s=time.perf_counter()-started,convergence='converged' if max(abs(pg))<=1e-6 else 'not converged',
                diagnostics=dict(initial=initial,support=support,n_starts=len(pairs),adam_iterations=steps,
                                 initial_log_states=x0.tolist(),refinement_iterations=int(best.nit),
                                 evaluations=sum(int(r.nfev) for r in candidates),selected_train_loss=float(L),
                                 projected_gradient=pg.tolist(),optimizer_success=bool(best.success),message=str(best.message),
                                 q0=float(off),v0=float(v0),bound_hit=bool(any(abs(best.x[j]-a)<1e-7 or abs(best.x[j]-b)<1e-7 for j,(a,b) in enumerate(bounds))),
                                 candidate_losses=[float(r.fun) for r in candidates]))

def akf(d,sc,initial='native',cov_mult=1.,smoke=False):
    start=time.perf_counter();u=d.q_obs[None]
    sigma=max(1e-4,float(H.MJ.robust_noise_var(u,d.t_obs)[0].sqrt()))
    cfg=AKFConfig(max_step_s=1/(240*sc['T']),position_process_std=.1*sigma,
                  velocity_process_std=sigma,parameter_process_std=0.,position_measurement_std=sigma,
                  initial_position_std=sigma*math.sqrt(cov_mult),initial_velocity_std=math.sqrt(cov_mult),
                  initial_parameter_std=math.log(100)*math.sqrt(cov_mult))
    selected=None;search=[]
    if initial=='native':
        def evaluate(pairs):
            try:
                r=run_akf_batched(d,[p[0] for p in pairs],[p[1] for p in pairs],cfg)
                if not bool(torch.isfinite(r.innovation_scores).all()):
                    raise FloatingPointError('nonfinite innovation likelihood')
                for i,p in enumerate(pairs):
                    val=float(r.innovation_scores[i]);search.append(dict(I0=p[0],c0=p[1],nll=val))
            except (FloatingPointError,RuntimeError,ValueError,OverflowError):
                if len(pairs)==1:search.append(dict(I0=pairs[0][0],c0=pairs[0][1],nll=float('inf')))
                else:
                    k=len(pairs)//2;evaluate(pairs[:k]);evaluate(pairs[k:])
        evaluate(H.grid())  # smoke must exercise the declared native search too
        usable=[r for r in search if np.isfinite(r['nll'])]
        assert usable,'all AKF starts failed'
        selected=min(usable,key=lambda r:r['nll'])
        cfg=replace(cfg,inertia_guess=selected['I0'],damping_guess=selected['c0'])
        ds=d
    else:
        cfg=replace(cfg,inertia_guess=initial['inertia'],damping_guess=initial['damping'],initial_velocity=initial['v0'])
        # Original run_akf initializes q from q_obs[0]. Use an offset coordinate
        # to realize the shared LS initial position without changing measurements.
        # A constant shift cannot change q_obs[0] relative to itself; therefore
        # preserve the original observed-q0 initialization and declare this limit.
        ds=d
    r=run_akf(ds,cfg,dense_t=d.t_obs[:1]);fs=r.filtered_state
    I,c,_=physical_parameters(fs[-1,2],fs[-1,3],'free_c')
    drift=(fs[-1,2:]-fs[max(0,len(fs)-6),2:]).abs().max()
    innov=r.innovations.numpy();var=r.innovation_variances.numpy()
    return dict(inertia=float(I),damping=float(c),q_hat=fs[:,0].tolist(),runtime_s=time.perf_counter()-start,
                convergence='finite filter pass',diagnostics=dict(config=cfg.__dict__,sigma=sigma,covariance_multiplier=cov_mult,
                   initial=initial,q0=float(d.q_obs[0]),q0_shared_limitation='original EKF fixes first q to observation; LS v0/I/c shared',
                   search=search,selected=selected,n_starts=len(search) if search else 1,
                   innovation_nis_mean=float(np.mean(innov[1:]**2/var[1:])),last_5_log_parameter_drift=float(drift),
                   final_covariance=r.filtered_covariance[-1].tolist()))
